negativeExample:
package example;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.AbstractMap;

public class MyClassNegative {
    public void testDifferentClass() {
        // Not a SimpleEntry constructor, should not match
        List<String> list = new ArrayList<String>();
    }

    public void testCustomEntry() {
        // Constructor of a different custom class, should not match
        class CustomEntry<K, V> {
            K k; V v;
            public CustomEntry(K k, V v) { this.k = k; this.v = v; }
        }
        CustomEntry<String, String> customEntry = new CustomEntry<String, String>("A", "B");
    }

    public void testAnonymousInnerClass() {
        // Anonymous inner class creation for SimpleEntry, which is syntactically different from a direct constructor call
        String key = "anon";
        Object value = new Object();
        Map.Entry<String, Object> anonEntry = new AbstractMap.SimpleEntry<String, Object>(key, value) {}; 
    }

    public void testAlreadyDiamond() {
        // Already uses diamond operator, should not match as the pattern requires explicit type arguments
        String key = "existing";
        Object value = "diamond";
        Map.Entry<String, Object> existingEntry = new AbstractMap.SimpleEntry<>(key, value);
    }
}

